PAGE_HTML = '<!DOCTYPE html>\n<html lang="en" class="dark">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>NSE Live Terminal — Nairobi Securities Exchange (NSEKE)</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="preconnect" href="https://fonts.googleapis.com" />\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet" />\n  <script>\n    tailwind.config = {\n      darkMode: \'class\',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: [\'Inter\', \'system-ui\', \'sans-serif\'],\n            mono: [\'JetBrains Mono\', \'monospace\']\n          },\n          colors: {\n            nse: {\n              bg: \'#000000\',\n              panel: \'#0a0a0a\',\n              elevated: \'#141414\',\n              hover: \'#1c1c1c\',\n              border: \'#262626\',\n              text: \'#ffffff\',\n              muted: \'#8c8c8c\',\n              green: \'#089981\',\n              red: \'#f23645\'\n            }\n          }\n        }\n      }\n    };\n  </script>\n  <style>\n    *, *::before, *::after {\n      border-radius: 0px !important;\n      box-sizing: border-box;\n    }\n    html, body {\n      margin: 0;\n      padding: 0;\n      background-color: #000000;\n      color: #ffffff;\n      font-family: \'Inter\', system-ui, sans-serif;\n      overflow-x: hidden;\n    }\n    .tabular-nums { font-variant-numeric: tabular-nums; }\n    ::-webkit-scrollbar { width: 5px; height: 5px; }\n    ::-webkit-scrollbar-track { background: #000000; }\n    ::-webkit-scrollbar-thumb { background: #333333; }\n    ::-webkit-scrollbar-thumb:hover { background: #ffffff; }\n    .tv-btn {\n      background: #000000;\n      color: #cccccc;\n      border: 1px solid #262626;\n      transition: background-color 0.1s ease, color 0.1s ease, border-color 0.1s ease;\n    }\n    .tv-btn:hover {\n      background: #1a1a1a;\n      color: #ffffff;\n      border-color: #555555;\n    }\n    .tv-btn.active {\n      background: #ffffff;\n      color: #000000;\n      border-color: #ffffff;\n      font-weight: 700;\n    }\n  </style>\n</head>\n<body class="bg-nse-bg text-nse-text min-h-screen flex flex-col select-none">\n\n  <!-- TOP COMMAND BAR -->\n  <header class="h-11 bg-nse-bg border-b border-nse-border px-2 flex items-center justify-between gap-2 shrink-0 z-30">\n    <div class="flex items-center gap-2 min-w-0">\n      <div class="flex items-center gap-2 pr-2 border-r border-nse-border">\n        <div class="w-6 h-6 bg-white text-black font-mono font-bold text-xs flex items-center justify-center">NSE</div>\n        <div class="leading-none">\n          <div class="text-xs font-bold tracking-wider uppercase">NSEKE TERMINAL</div>\n          <div class="text-[9px] font-mono text-nse-muted">NAIROBI SECURITIES EXCHANGE</div>\n        </div>\n      </div>\n\n      <!-- Workspace Navigation -->\n      <nav class="flex items-center gap-1">\n        <button id="ws-btn-charts" class="tv-btn active px-2.5 py-1 text-xs font-mono uppercase">Supercharts</button>\n        <button id="ws-btn-screener" class="tv-btn px-2.5 py-1 text-xs font-mono uppercase">All NSE Symbols (<span id="symbol-count-badge">0</span>)</button>\n        <button id="ws-btn-connectors" class="tv-btn px-2.5 py-1 text-xs font-mono uppercase">TV Scrapers &amp; WS</button>\n      </nav>\n    </div>\n\n    <!-- Live Status & Sync Controls -->\n    <div class="flex items-center gap-1.5 shrink-0">\n      <div class="hidden md:flex items-center gap-1.5 border border-nse-border px-2 py-1 text-[11px] font-mono">\n        <span id="session-dot" class="w-2 h-2 bg-nse-green inline-block"></span>\n        <span id="session-status-text">NSE SESSION</span>\n        <span class="text-nse-muted">|</span>\n        <span id="eat-clock" class="tabular-nums text-white">--:--:-- EAT</span>\n      </div>\n\n      <button id="sync-tv-btn" class="tv-btn px-2.5 py-1 text-xs font-mono flex items-center gap-1.5" title="Scrape all NSEKE symbols & historical bars from TradingView">\n        <span class="w-1.5 h-1.5 bg-white inline-block"></span>\n        <span>SCRAPE TRADINGVIEW</span>\n        <span id="tv-api-status-pill" class="px-1 bg-white text-black text-[10px] font-bold">READY</span>\n      </button>\n\n      <button id="open-paste-modal-btn" class="tv-btn px-2.5 py-1 text-xs font-mono uppercase">Import CSV</button>\n    </div>\n  </header>\n\n  <!-- WORKSPACE 1: SUPERCHARTS -->\n  <main id="workspace-charts" class="flex-1 flex flex-col lg:flex-row min-h-[calc(100vh-44px)] overflow-hidden">\n\n    <!-- LEFT DRAWING TOOLBAR -->\n    <aside class="w-full lg:w-10 bg-nse-bg border-b lg:border-b-0 lg:border-r border-nse-border flex lg:flex-col items-center justify-between lg:justify-start p-1 gap-1 shrink-0">\n      <div class="flex lg:flex-col items-center gap-1">\n        <button data-tool="crosshair" class="tool-btn tv-btn active w-8 h-8 flex items-center justify-center font-mono text-xs" title="Crosshair">+</button>\n        <button data-tool="trendline" class="tool-btn tv-btn w-8 h-8 flex items-center justify-center font-mono text-xs" title="Trend Line">/</button>\n        <button data-tool="hline" class="tool-btn tv-btn w-8 h-8 flex items-center justify-center font-mono text-xs" title="Horizontal Line">—</button>\n        <button data-tool="fib" class="tool-btn tv-btn w-8 h-8 flex items-center justify-center font-mono text-xs" title="Fibonacci Retracement">F</button>\n        <button data-tool="rect" class="tool-btn tv-btn w-8 h-8 flex items-center justify-center font-mono text-xs" title="Price Range Box">[]</button>\n      </div>\n      <div class="flex lg:flex-col items-center gap-1 lg:mt-auto">\n        <button id="reset-scales-btn" class="tv-btn w-8 h-8 flex items-center justify-center font-mono text-[10px]" title="Reset Price & Time Scales (Auto-Fit)">FIT</button>\n        <button id="clear-drawings-btn" class="tv-btn w-8 h-8 flex items-center justify-center font-mono text-[10px]" title="Clear All Drawings">CLR</button>\n      </div>\n    </aside>\n\n    <!-- CENTER CHART COLUMN -->\n    <section class="flex-1 flex flex-col min-w-0 bg-nse-bg">\n      <!-- Chart Sub-Toolbar: Symbol, Timeframes, Chart Styles, Indicators -->\n      <div class="min-h-9 bg-nse-panel border-b border-nse-border px-2 py-1 flex flex-wrap items-center justify-between gap-2">\n        <div class="flex flex-wrap items-center gap-1.5">\n          <!-- Active Ticker Header -->\n          <div class="flex items-center gap-1.5 pr-2 border-r border-nse-border">\n            <span id="chart-symbol-badge" class="px-1.5 py-0.5 bg-white text-black font-mono font-bold text-xs">NSEKE:SCOM</span>\n            <span id="chart-company-name" class="text-xs font-semibold text-white truncate max-w-[160px]">Safaricom PLC</span>\n            <a id="tv-external-link" href="https://www.tradingview.com/chart/IInGcnS5/?symbol=NSEKE%3ASCOM" target="_blank" rel="noopener noreferrer" class="text-[10px] font-mono text-nse-muted hover:text-white underline ml-1">TV ↗</a>\n          </div>\n\n          <!-- Timeframe Selector -->\n          <div class="flex items-center gap-0.5" id="timeframe-bar">\n            <button data-tf="1m" class="tf-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">1m</button>\n            <button data-tf="5m" class="tf-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">5m</button>\n            <button data-tf="15m" class="tf-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">15m</button>\n            <button data-tf="1H" class="tf-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">1H</button>\n            <button data-tf="1D" class="tf-btn tv-btn active px-1.5 py-0.5 font-mono text-[11px]">1D</button>\n            <button data-tf="1W" class="tf-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">1W</button>\n            <button data-tf="1M" class="tf-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">1M</button>\n          </div>\n\n          <span class="text-nse-border">|</span>\n\n          <!-- Chart Style -->\n          <div class="flex items-center gap-0.5">\n            <button data-style="candles" class="style-btn tv-btn active px-1.5 py-0.5 font-mono text-[11px]">Candles</button>\n            <button data-style="hollow" class="style-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">Hollow</button>\n            <button data-style="ohlc" class="style-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">Bars</button>\n            <button data-style="line" class="style-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">Line</button>\n          </div>\n\n          <span class="text-nse-border">|</span>\n\n          <!-- Technical Overlays -->\n          <div class="flex items-center gap-0.5">\n            <button id="ind-sma20" class="ind-btn tv-btn active px-1.5 py-0.5 font-mono text-[11px]">SMA20</button>\n            <button id="ind-ema50" class="ind-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">EMA50</button>\n            <button id="ind-bb" class="ind-btn tv-btn px-1.5 py-0.5 font-mono text-[11px]">BB</button>\n            <button id="ind-vol" class="ind-btn tv-btn active px-1.5 py-0.5 font-mono text-[11px]">VOL</button>\n          </div>\n        </div>\n\n        <!-- Scale Scroll/Zoom Hint -->\n        <div class="text-[10px] font-mono text-nse-muted hidden xl:flex items-center gap-2">\n          <span>SCROLL/DRAG Y-AXIS: PRICE SCALE</span>\n          <span>•</span>\n          <span>SCROLL/DRAG X-AXIS: TIME SCALE</span>\n          <span>•</span>\n          <span>DBL-CLICK AXIS: RESET</span>\n        </div>\n      </div>\n\n      <!-- OHLCV Live Legend Bar -->\n      <div class="bg-nse-bg border-b border-nse-border px-2.5 py-1 flex flex-wrap items-center justify-between gap-2 text-xs font-mono tabular-nums">\n        <div class="flex flex-wrap items-center gap-3">\n          <span>O <strong id="ohlc-o" class="text-white">--</strong></span>\n          <span>H <strong id="ohlc-h" class="text-white">--</strong></span>\n          <span>L <strong id="ohlc-l" class="text-white">--</strong></span>\n          <span>C <strong id="ohlc-c" class="text-white">--</strong></span>\n          <span id="ohlc-chg" class="font-semibold">--</span>\n          <span class="text-nse-muted">VOL <strong id="ohlc-v" class="text-white">--</strong></span>\n        </div>\n        <div class="flex items-center gap-2 text-[11px]">\n          <span class="text-nse-muted">BARS: <strong id="bar-count-label" class="text-white">0</strong></span>\n          <span class="text-nse-muted">SOURCE: <strong id="data-source-label" class="text-white">TRADINGVIEW NSEKE</strong></span>\n        </div>\n      </div>\n\n      <!-- INTERACTIVE CHART CANVAS CONTAINER -->\n      <div id="chart-container" class="relative flex-1 min-h-[420px] w-full bg-nse-bg overflow-hidden cursor-crosshair">\n        <canvas id="main-chart-canvas" class="block w-full h-full"></canvas>\n\n        <!-- Empty / Scraping Overlay (Shown only when 0 real bars are loaded yet) -->\n        <div id="chart-empty-overlay" class="absolute inset-0 bg-black/90 flex flex-col items-center justify-center p-6 text-center z-20">\n          <div class="border border-white bg-black p-5 max-w-md w-full space-y-3">\n            <div class="text-xs font-mono uppercase tracking-widest text-nse-muted">NO SYNTHETIC / MOCK DATA</div>\n            <h2 id="empty-overlay-title" class="text-base font-bold font-mono text-white">CONNECTING TO TRADINGVIEW (NSEKE)...</h2>\n            <p id="empty-overlay-desc" class="text-xs text-nse-muted leading-relaxed">\n              Querying TradingView Kenya Scanner and WebSocket (wss://data.tradingview.com) for verified NSEKE OHLCV bars. If your browser blocks cross-origin requests, connect a local bridge or paste TradingView CSV data.\n            </p>\n            <div class="flex flex-wrap items-center justify-center gap-2 pt-2">\n              <button id="overlay-retry-btn" class="tv-btn active px-3 py-1.5 text-xs font-mono uppercase">Retry TradingView Scrape</button>\n              <button id="overlay-bridge-btn" class="tv-btn px-3 py-1.5 text-xs font-mono uppercase">Setup Local WS/REST Bridge</button>\n              <button id="overlay-csv-btn" class="tv-btn px-3 py-1.5 text-xs font-mono uppercase">Paste TV CSV</button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- BOTTOM TIME & SCALE CONTROL STRIP -->\n      <div class="h-8 bg-nse-panel border-t border-nse-border px-2 flex items-center justify-between text-[11px] font-mono">\n        <div class="flex items-center gap-1">\n          <button id="zoom-in-x-btn" class="tv-btn px-2 py-0.5" title="Zoom In Time Axis">+</button>\n          <button id="zoom-out-x-btn" class="tv-btn px-2 py-0.5" title="Zoom Out Time Axis">-</button>\n          <button id="pan-left-btn" class="tv-btn px-2 py-0.5" title="Scroll Left in Time">&lt;</button>\n          <button id="pan-right-btn" class="tv-btn px-2 py-0.5" title="Scroll Right to Latest">&gt;</button>\n          <button id="jump-latest-btn" class="tv-btn px-2 py-0.5">LATEST</button>\n        </div>\n        <div class="flex items-center gap-2 text-nse-muted">\n          <span>Y-SCALE: <strong id="y-scale-readout" class="text-white">AUTO (100%)</strong></span>\n          <button id="reset-y-scale-btn" class="tv-btn px-1.5 py-0.5 text-[10px]">AUTO Y</button>\n        </div>\n      </div>\n    </section>\n\n    <!-- RIGHT SIDEBAR: NSE WATCHLIST & SYMBOL DETAILS -->\n    <aside class="w-full lg:w-80 bg-nse-panel border-t lg:border-t-0 lg:border-l border-nse-border flex flex-col shrink-0">\n      <!-- Watchlist Search -->\n      <div class="p-2 border-b border-nse-border space-y-1.5">\n        <div class="flex items-center justify-between">\n          <span class="text-xs font-mono font-bold uppercase">NSEKE WATCHLIST</span>\n          <span id="watchlist-count" class="text-[11px] font-mono text-nse-muted">0 SYMBOLS</span>\n        </div>\n        <input id="watchlist-search" type="text" placeholder="Filter symbol or company (e.g. SCOM, EQTY)..." class="w-full bg-black border border-nse-border px-2 py-1 text-xs font-mono text-white focus:outline-none focus:border-white" />\n      </div>\n\n      <!-- Watchlist Column Headers -->\n      <div class="grid grid-cols-12 px-2 py-1 bg-black border-b border-nse-border text-[10px] font-mono text-nse-muted uppercase">\n        <div class="col-span-5">Symbol</div>\n        <div class="col-span-4 text-right">Last (KES)</div>\n        <div class="col-span-3 text-right">Chg%</div>\n      </div>\n\n      <!-- Watchlist Items -->\n      <div id="watchlist-body" class="flex-1 overflow-y-auto max-h-[340px] lg:max-h-none divide-y divide-nse-border">\n        <div class="p-4 text-xs font-mono text-nse-muted text-center">\n          Awaiting live NSEKE symbols from TradingView Scanner...\n        </div>\n      </div>\n\n      <!-- Selected Security Quote & Fundamentals Card -->\n      <div class="border-t border-nse-border bg-black p-2.5 space-y-2 text-xs font-mono">\n        <div class="flex items-start justify-between">\n          <div>\n            <div id="detail-ticker" class="font-bold text-sm text-white">NSEKE:SCOM</div>\n            <div id="detail-name" class="text-[11px] text-nse-muted">Safaricom PLC</div>\n          </div>\n          <div class="text-right tabular-nums">\n            <div id="detail-price" class="text-base font-bold text-white">--</div>\n            <div id="detail-change" class="text-[11px]">--</div>\n          </div>\n        </div>\n\n        <div class="grid grid-cols-2 gap-1.5 pt-1 border-t border-nse-border text-[11px] tabular-nums">\n          <div class="flex justify-between"><span class="text-nse-muted">OPEN</span><span id="detail-open">--</span></div>\n          <div class="flex justify-between"><span class="text-nse-muted">PREV</span><span id="detail-prev">--</span></div>\n          <div class="flex justify-between"><span class="text-nse-muted">HIGH</span><span id="detail-high">--</span></div>\n          <div class="flex justify-between"><span class="text-nse-muted">LOW</span><span id="detail-low">--</span></div>\n          <div class="flex justify-between"><span class="text-nse-muted">52W H</span><span id="detail-52h">--</span></div>\n          <div class="flex justify-between"><span class="text-nse-muted">52W L</span><span id="detail-52l">--</span></div>\n          <div class="flex justify-between"><span class="text-nse-muted">VOL</span><span id="detail-vol">--</span></div>\n          <div class="flex justify-between"><span class="text-nse-muted">RSI(14)</span><span id="detail-rsi">--</span></div>\n        </div>\n      </div>\n    </aside>\n  </main>\n\n  <!-- WORKSPACE 2: ALL SCRAPED NSE SYMBOLS TABLE -->\n  <section id="workspace-screener" class="hidden flex-1 bg-nse-bg p-3 overflow-auto">\n    <div class="max-w-7xl mx-auto space-y-3">\n      <div class="flex flex-wrap items-center justify-between gap-2 border-b border-nse-border pb-2">\n        <div>\n          <h1 class="text-sm font-mono font-bold uppercase">ALL SCRAPED NAIROBI SECURITIES EXCHANGE (NSEKE) SYMBOLS</h1>\n          <p class="text-xs font-mono text-nse-muted">Live fields pulled directly from scanner.tradingview.com/kenya/scan</p>\n        </div>\n        <button id="screener-rescrape-btn" class="tv-btn active px-3 py-1.5 text-xs font-mono uppercase">Refresh All NSEKE Symbols</button>\n      </div>\n      <div class="border border-nse-border overflow-x-auto">\n        <table class="w-full text-left font-mono text-xs tabular-nums">\n          <thead class="bg-nse-panel border-b border-nse-border text-[11px] text-nse-muted uppercase">\n            <tr>\n              <th class="p-2">Ticker</th>\n              <th class="p-2">Description</th>\n              <th class="p-2 text-right">Last</th>\n              <th class="p-2 text-right">Chg%</th>\n              <th class="p-2 text-right">Open</th>\n              <th class="p-2 text-right">High</th>\n              <th class="p-2 text-right">Low</th>\n              <th class="p-2 text-right">Volume</th>\n              <th class="p-2 text-right">Perf 1W</th>\n              <th class="p-2 text-right">Perf 1M</th>\n              <th class="p-2 text-right">Perf 1Y</th>\n              <th class="p-2 text-right">52W High</th>\n              <th class="p-2 text-right">52W Low</th>\n            </tr>\n          </thead>\n          <tbody id="screener-table-body" class="divide-y divide-nse-border">\n            <tr><td colspan="13" class="p-4 text-center text-nse-muted">No symbols loaded yet. Click "Refresh All NSEKE Symbols".</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </section>\n\n  <!-- WORKSPACE 3: TRADINGVIEW SCRAPERS & WEBSOCKET BRIDGE -->\n  <section id="workspace-connectors" class="hidden flex-1 bg-nse-bg p-3 overflow-auto">\n    <div class="max-w-5xl mx-auto space-y-4 font-mono text-xs">\n      <div class="border border-nse-border bg-nse-panel p-4 space-y-3">\n        <h2 class="text-sm font-bold uppercase text-white">1. LOCAL TRADINGVIEW WEBSOCKET / FASTAPI BRIDGE</h2>\n        <p class="text-nse-muted">\n          TradingView limits browser cross-origin WebSocket &amp; Scanner requests unless routed through a local bridge or CORS proxy. Run any of the open-source TradingView adapters below and connect this UI directly:\n        </p>\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-3">\n          <div class="border border-nse-border bg-black p-3 space-y-2">\n            <div class="font-bold text-white">Cloud / Online API Endpoint (cloud_nse_api.py)</div>\n            <input id="rest-bridge-url" type="text" placeholder="https://your-app.onrender.com (leave blank for built-in cloud relays)" class="w-full bg-nse-panel border border-nse-border px-2 py-1 text-white" />\n            <button id="fetch-rest-bridge-btn" class="tv-btn active px-3 py-1 uppercase">Sync Online Endpoint</button>\n          </div>\n          <div class="border border-nse-border bg-black p-3 space-y-2">\n            <div class="font-bold text-white">Local WebSocket Bridge (@mathieuc/tradingview)</div>\n            <input id="ws-bridge-url" type="text" value="ws://localhost:8765" class="w-full bg-nse-panel border border-nse-border px-2 py-1 text-white" />\n            <button id="connect-ws-bridge-btn" class="tv-btn active px-3 py-1 uppercase">Connect Local WS</button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Ready-to-run Node.js (Mathieu2301/TradingView-API) & Python (rongardF/tvdatafeed) Scripts -->\n      <div class="grid grid-cols-1 md:grid-cols-2 gap-3">\n        <div class="border border-nse-border bg-nse-panel p-3 space-y-2">\n          <div class="font-bold uppercase">Node.js Bridge (@mathieuc/tradingview)</div>\n          <pre class="bg-black border border-nse-border p-2.5 text-[11px] overflow-x-auto text-gray-300">npm i @mathieuc/tradingview ws\n# server.js\nconst TradingView = require(\'@mathieuc/tradingview\');\nconst WebSocket = require(\'ws\');\nconst wss = new WebSocket.Server({ port: 8765 });\nconst client = new TradingView.Client();\n\nwss.on(\'connection\', (ws) => {\n  ws.on(\'message\', (raw) => {\n    const { symbol = \'NSEKE:SCOM\', timeframe = \'D\', range = 1000 } = JSON.parse(raw);\n    const chart = new client.Session.Chart();\n    chart.setMarket(symbol, { timeframe, range });\n    chart.onUpdate(() => {\n      if (!chart.periods.length) return;\n      const bars = chart.periods.slice().reverse().map(p => ({\n        date: new Date(p.time * 1000).toISOString().slice(0, 16).replace(\'T\', \' \'),\n        open: p.open, high: p.max, low: p.min, close: p.close, volume: p.volume\n      }));\n      ws.send(JSON.stringify({ type: \'history\', symbol, timeframe, bars }));\n    });\n  });\n});</pre>\n        </div>\n\n        <div class="border border-nse-border bg-nse-panel p-3 space-y-2">\n          <div class="font-bold uppercase">Python Bridge (rongardF/tvdatafeed + FastAPI)</div>\n          <pre class="bg-black border border-nse-border p-2.5 text-[11px] overflow-x-auto text-gray-300">pip install fastapi uvicorn git+https://github.com/rongardF/tvdatafeed.git\n# api.py\nfrom fastapi import FastAPI\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom tvDatafeed import TvDatafeed, Interval\n\napp = FastAPI()\napp.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])\ntv = TvDatafeed()\n\n@app.get("/history")\ndef history(symbol: str = "SCOM", interval: str = "1D", bars: int = 1000):\n    df = tv.get_hist(symbol=symbol, exchange="NSEKE", interval=Interval.in_daily, n_bars=bars)\n    return [{"date": str(idx)[:16], "open": r.open, "high": r.high, "low": r.low, "close": r.close, "volume": r.volume} for idx, r in df.iterrows()]</pre>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- CSV IMPORT MODAL -->\n  <div id="csv-modal" class="hidden fixed inset-0 bg-black/85 z-50 flex items-center justify-center p-4">\n    <div class="bg-nse-panel border border-white max-w-xl w-full p-4 space-y-3 font-mono text-xs">\n      <div class="flex items-center justify-between border-b border-nse-border pb-2">\n        <span class="font-bold uppercase">PASTE TRADINGVIEW EXPORTED CSV (TIME, OPEN, HIGH, LOW, CLOSE, VOLUME)</span>\n        <button id="close-csv-modal-btn" class="tv-btn px-2 py-0.5">X</button>\n      </div>\n      <textarea id="csv-paste-area" rows="8" placeholder="time,open,high,low,close,Volume&#10;2026-11-10,34.50,35.10,34.40,34.95,2450000&#10;2026-11-11,34.95,35.20,34.80,35.00,1920000" class="w-full bg-black border border-nse-border p-2 text-white focus:outline-none focus:border-white"></textarea>\n      <div class="flex justify-end gap-2">\n        <button id="apply-csv-btn" class="tv-btn active px-3 py-1.5 uppercase">Load Into Chart</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- TOAST NOTIFICATION -->\n  <div id="toast-banner" class="hidden fixed bottom-10 right-3 bg-white text-black border border-black px-3 py-2 text-xs font-mono font-bold z-50"></div>\n\n  <script>\n    // =========================================================================\n    // STATE (100% REAL SCRAPED / IMPORTED DATA ONLY — ZERO MOCK GENERATORS)\n    // =========================================================================\n    const state = {\n      selectedTicker: \'SCOM\',\n      timeframe: \'1D\',\n      chartStyle: \'candles\',\n      activeTool: \'crosshair\',\n      indicators: { sma20: true, ema50: false, bb: false, vol: true },\n      stocks: [],         // Populated exclusively by TradingView Kenya Scanner or CSV/Bridge\n      historyCache: {},   // Key: `${ticker}_${tf}` -> Array<{date, open, high, low, close, volume}>\n      drawings: {},       // Key: ticker -> Array of drawing objects\n      activeDraft: null,\n      searchQuery: \'\',\n      // Interactive X (Time) & Y (Price) Scale State\n      viewport: {\n        rightOffset: 0,       // Number of bars scrolled from the right edge (0 = latest bar visible)\n        visibleBars: 90,      // Number of candles shown horizontally (zoom level)\n        yZoom: 1.0,           // Vertical price scale multiplier (>1 compresses candles, <1 stretches)\n        yPanOffset: 0         // Vertical price shift in price units\n      },\n      pointer: {\n        inside: false,\n        x: 0,\n        y: 0,\n        dragMode: null,       // \'pan-xy\' | \'scale-y\' | \'scale-x\' | \'draw\'\n        dragStartX: 0,\n        dragStartY: 0,\n        startRightOffset: 0,\n        startVisibleBars: 90,\n        startYZoom: 1.0,\n        startYPanOffset: 0\n      }\n    };\n\n    const CORS_PROXIES = [\n      (url) => url,\n      (url) => `https://corsproxy.io/?url=${encodeURIComponent(url)}`,\n      (url) => `https://corsproxy.io/?${encodeURIComponent(url)}`,\n      (url) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(url)}`,\n      (url) => `https://thingproxy.freeboard.io/fetch/${url}`,\n      (url) => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`\n    ];\n\n    function showToast(msg) {\n      const el = document.getElementById(\'toast-banner\');\n      el.textContent = msg;\n      el.classList.remove(\'hidden\');\n      clearTimeout(el._timer);\n      el._timer = setTimeout(() => el.classList.add(\'hidden\'), 4200);\n    }\n\n    function updateEatClock() {\n      const now = new Date();\n      const eatStr = new Intl.DateTimeFormat(\'en-GB\', {\n        timeZone: \'Africa/Nairobi\',\n        hour: \'2-digit\',\n        minute: \'2-digit\',\n        second: \'2-digit\',\n        hour12: false\n      }).format(now);\n      document.getElementById(\'eat-clock\').textContent = `${eatStr} EAT`;\n\n      const eatHour = Number(new Intl.DateTimeFormat(\'en-GB\', {\n        timeZone: \'Africa/Nairobi\',\n        hour: \'2-digit\',\n        hour12: false\n      }).format(now));\n      const dayName = new Intl.DateTimeFormat(\'en-US\', { timeZone: \'Africa/Nairobi\', weekday: \'short\' }).format(now);\n      const isWeekend = dayName === \'Sat\' || dayName === \'Sun\';\n      const isOpen = !isWeekend && eatHour >= 9 && eatHour < 15;\n      document.getElementById(\'session-dot\').className = `w-2 h-2 inline-block ${isOpen ? \'bg-nse-green\' : \'bg-nse-red\'}`;\n      document.getElementById(\'session-status-text\').textContent = isOpen ? \'NSE OPEN\' : \'NSE CLOSED\';\n    }\n\n    // =========================================================================\n    // TRADINGVIEW ALL-NSE SYMBOL SCANNER & WEBSOCKET SCRAPER\n    // =========================================================================\n    const tvScraper = {\n      ws: null,\n      directTvWs: null,\n\n      parseTvFrames(raw) {\n        const frames = [];\n        let idx = 0;\n        while (idx < raw.length) {\n          if (raw.slice(idx, idx + 3) !== \'~m~\') break;\n          const lenStart = idx + 3;\n          const lenEnd = raw.indexOf(\'~m~\', lenStart);\n          if (lenEnd === -1) break;\n          const len = parseInt(raw.slice(lenStart, lenEnd), 10);\n          const payloadStart = lenEnd + 3;\n          frames.push(raw.slice(payloadStart, payloadStart + len));\n          idx = payloadStart + len;\n        }\n        return frames;\n      },\n\n      encodeTvFrame(obj) {\n        const str = typeof obj === \'string\' ? obj : JSON.stringify(obj);\n        return `~m~${str.length}~m~${str}`;\n      },\n\n      async scrapeAllNseSymbols() {\n        const pill = document.getElementById(\'tv-api-status-pill\');\n        pill.textContent = \'SCANNING...\';\n\n        const scannerUrl = \'https://scanner.tradingview.com/kenya/scan\';\n        const customCloudUrl = document.getElementById(\'rest-bridge-url\')?.value?.trim();\n        const sameOriginApi = (window.location.protocol.startsWith(\'http\') && !window.location.hostname.includes(\'localhost\'))\n          ? window.location.origin\n          : \'\';\n        const apiBase = (customCloudUrl && customCloudUrl.startsWith(\'http\')) ? customCloudUrl : sameOriginApi;\n\n        if (apiBase) {\n          try {\n            const res = await fetch(`${apiBase.replace(/\\/$/, \'\')}/api/symbols`);\n            if (res.ok) {\n              const json = await res.json();\n              if (json.ok && Array.isArray(json.symbols) && json.symbols.length > 0) {\n                state.stocks = json.symbols;\n                if (!state.stocks.some(s => s.ticker === state.selectedTicker)) {\n                  state.selectedTicker = state.stocks[0].ticker;\n                }\n                pill.textContent = `${state.stocks.length} NSEKE`;\n                renderAll();\n                showToast(`Loaded ${state.stocks.length} live NSEKE symbols from Vercel API.`);\n                return true;\n              }\n            }\n          } catch (_) {}\n        }\n\n        const payload = {\n          filter: [{ left: \'exchange\', operation: \'equal\', right: \'NSEKE\' }],\n          options: { lang: \'en\' },\n          symbols: { query: { types: [] }, tickers: [] },\n          columns: [\n            \'name\', \'description\', \'close\', \'change\', \'change_abs\',\n            \'open\', \'high\', \'low\', \'volume\', \'Perf.W\', \'Perf.1M\',\n            \'Perf.3M\', \'Perf.Y\', \'price_52_week_high\', \'price_52_week_low\',\n            \'RSI\', \'SMA20\', \'EMA50\', \'sector\'\n          ],\n          sort: { sortBy: \'volume\', sortOrder: \'desc\' },\n          range: [0, 200]\n        };\n\n        // Try GET-based TradingView symbol search & screener endpoints via public cloud relays as well\n        const getFallbackUrls = [\n          \'https://symbol-search.tradingview.com/symbol_search/v3/?text=&hl=1&exchange=NSEKE&lang=en&search_type=stocks&domain=production&sort_by_country=KE\'\n        ];\n\n        for (const buildUrl of CORS_PROXIES) {\n          try {\n            const target = buildUrl(scannerUrl);\n            const res = await fetch(target, {\n              method: \'POST\',\n              headers: { \'Content-Type\': \'application/json\' },\n              body: JSON.stringify(payload)\n            });\n            if (!res.ok) continue;\n            const json = await res.json();\n            if (Array.isArray(json.data) && json.data.length > 0) {\n              state.stocks = json.data.map(row => {\n                const d = row.d || [];\n                const ticker = (d[0] || row.s?.split(\':\')[1] || \'\').toUpperCase();\n                const close = Number(d[2] || 0);\n                const chgAbs = Number(d[4] || 0);\n                return {\n                  ticker,\n                  name: d[1] || ticker,\n                  price: close,\n                  changePct: Number(d[3] || 0),\n                  change: chgAbs,\n                  prevClose: +(close - chgAbs).toFixed(2),\n                  open: Number(d[5] || close),\n                  high: Number(d[6] || close),\n                  low: Number(d[7] || close),\n                  volume: Math.round(Number(d[8] || 0)),\n                  perfW: d[9] != null ? Number(d[9]) : null,\n                  perf1M: d[10] != null ? Number(d[10]) : null,\n                  perf3M: d[11] != null ? Number(d[11]) : null,\n                  perf1Y: d[12] != null ? Number(d[12]) : null,\n                  high52: d[13] != null ? Number(d[13]) : null,\n                  low52: d[14] != null ? Number(d[14]) : null,\n                  rsi: d[15] != null ? Number(d[15]) : null,\n                  sma20: d[16] != null ? Number(d[16]) : null,\n                  ema50: d[17] != null ? Number(d[17]) : null,\n                  sector: d[18] || \'NSEKE\'\n                };\n              }).filter(s => s.ticker && s.price > 0);\n\n              if (!state.stocks.some(s => s.ticker === state.selectedTicker) && state.stocks.length > 0) {\n                state.selectedTicker = state.stocks[0].ticker;\n              }\n              pill.textContent = `${state.stocks.length} NSEKE`;\n              renderAll();\n              showToast(`Scraped ${state.stocks.length} live NSEKE symbols from TradingView Cloud.`);\n              return true;\n            }\n          } catch (_) {\n            // Try next cloud relay\n          }\n        }\n\n        // Secondary GET-only symbol discovery via public cloud proxies\n        for (const rawUrl of getFallbackUrls) {\n          for (const buildUrl of CORS_PROXIES) {\n            try {\n              const res = await fetch(buildUrl(rawUrl));\n              if (!res.ok) continue;\n              const json = await res.json();\n              const list = Array.isArray(json.symbols) ? json.symbols : Array.isArray(json) ? json : [];\n              if (list.length > 0) {\n                state.stocks = list.map(item => {\n                  const ticker = (item.symbol || \'\').replace(/<[^>]+>/g, \'\').toUpperCase();\n                  return {\n                    ticker,\n                    name: (item.description || ticker).replace(/<[^>]+>/g, \'\'),\n                    price: 0,\n                    changePct: 0,\n                    change: 0,\n                    prevClose: 0,\n                    open: 0,\n                    high: 0,\n                    low: 0,\n                    volume: 0,\n                    sector: item.type || \'NSEKE\'\n                  };\n                }).filter(s => s.ticker);\n                if (state.stocks.length > 0) {\n                  pill.textContent = `${state.stocks.length} SYMS`;\n                  renderAll();\n                  showToast(`Discovered ${state.stocks.length} NSEKE symbols online.`);\n                  return true;\n                }\n              }\n            } catch (_) {}\n          }\n        }\n\n        pill.textContent = \'ONLINE BLOCKED\';\n        document.getElementById(\'empty-overlay-title\').textContent = \'PUBLIC RELAYS RATE-LIMITED — DEPLOY FREE CLOUD API\';\n        return false;\n      },\n\n      async fetchDirectTradingViewWs(ticker, tf = \'1D\', barCount = 500) {\n        const customCloudUrl = document.getElementById(\'rest-bridge-url\')?.value?.trim();\n        const sameOriginApi = (window.location.protocol.startsWith(\'http\') && !window.location.hostname.includes(\'localhost\'))\n          ? window.location.origin\n          : \'\';\n        const apiBase = (customCloudUrl && customCloudUrl.startsWith(\'http\')) ? customCloudUrl : sameOriginApi;\n\n        if (apiBase) {\n          try {\n            const res = await fetch(`${apiBase.replace(/\\/$/, \'\')}/api/history?symbol=${encodeURIComponent(ticker)}&tf=${encodeURIComponent(tf)}&bars=${barCount}`);\n            if (res.ok) {\n              const json = await res.json();\n              if (json.ok && Array.isArray(json.bars) && json.bars.length > 0) {\n                state.historyCache[`${ticker}_${tf}`] = json.bars;\n                document.getElementById(\'tv-api-status-pill\').textContent = `VERCEL (${json.bars.length})`;\n                renderAll();\n                showToast(`Loaded ${json.bars.length} real ${tf} bars for NSEKE:${ticker} from Vercel API.`);\n                return true;\n              }\n            }\n          } catch (_) {}\n        }\n\n        return new Promise((resolve) => {\n          try {\n            if (this.directTvWs) {\n              try { this.directTvWs.close(); } catch (_) {}\n            }\n            const tfMap = { \'1m\': \'1\', \'5m\': \'5\', \'15m\': \'15\', \'1H\': \'60\', \'1D\': \'D\', \'1W\': \'W\', \'1M\': \'M\' };\n            const resolution = tfMap[tf] || \'D\';\n            const chartSession = \'cs_\' + Math.random().toString(36).slice(2, 14);\n            const ws = new WebSocket(\'wss://data.tradingview.com/socket.io/websocket?from=chart%2FIInGcnS5%2F\');\n            this.directTvWs = ws;\n            let resolved = false;\n\n            const timer = setTimeout(() => {\n              if (!resolved) {\n                resolved = true;\n                try { ws.close(); } catch (_) {}\n                resolve(false);\n              }\n            }, 6000);\n\n            ws.onopen = () => {\n              ws.send(this.encodeTvFrame({ m: \'set_auth_token\', p: [\'unauthorized_user_token\'] }));\n              ws.send(this.encodeTvFrame({ m: \'chart_create_session\', p: [chartSession, \'\'] }));\n              ws.send(this.encodeTvFrame({\n                m: \'resolve_symbol\',\n                p: [chartSession, \'sds_sym_1\', `={"adjustment":"splits","session":"regular","symbol":"NSEKE:${ticker}"}`]\n              }));\n              ws.send(this.encodeTvFrame({\n                m: \'create_series\',\n                p: [chartSession, \'sds_1\', \'s1\', \'sds_sym_1\', resolution, barCount, \'\']\n              }));\n            };\n\n            ws.onmessage = (evt) => {\n              const frames = this.parseTvFrames(evt.data || \'\');\n              for (const frame of frames) {\n                if (frame.startsWith(\'~h~\')) {\n                  ws.send(this.encodeTvFrame(frame));\n                  continue;\n                }\n                if (!frame.startsWith(\'{\')) continue;\n                try {\n                  const pkt = JSON.parse(frame);\n                  if (pkt.m === \'timescale_update\' || pkt.m === \'du\') {\n                    const seriesData = pkt.p?.[1]?.sds_1?.s;\n                    if (Array.isArray(seriesData) && seriesData.length > 0) {\n                      const bars = seriesData.map(item => {\n                        const [ts, o, h, l, c, v] = item.v || [];\n                        const d = new Date(ts * 1000);\n                        const dateStr = [\'1\', \'5\', \'15\', \'60\'].includes(resolution)\n                          ? d.toISOString().slice(0, 16).replace(\'T\', \' \')\n                          : d.toISOString().slice(0, 10);\n                        return {\n                          date: dateStr,\n                          open: +Number(o).toFixed(2),\n                          high: +Number(h).toFixed(2),\n                          low: +Number(l).toFixed(2),\n                          close: +Number(c).toFixed(2),\n                          volume: Math.round(Number(v || 0))\n                        };\n                      }).filter(b => b.close > 0);\n\n                      if (bars.length > 0) {\n                        state.historyCache[`${ticker}_${tf}`] = bars;\n                        const last = bars[bars.length - 1];\n                        const prev = bars[bars.length - 2];\n                        let st = state.stocks.find(s => s.ticker === ticker);\n                        if (!st) {\n                          st = { ticker, name: `NSEKE:${ticker}`, price: last.close, open: last.open, high: last.high, low: last.low, prevClose: prev ? prev.close : last.open, change: 0, changePct: 0, volume: last.volume };\n                          state.stocks.unshift(st);\n                        }\n                        st.open = last.open;\n                        st.high = last.high;\n                        st.low = last.low;\n                        st.price = last.close;\n                        if (prev) st.prevClose = prev.close;\n                        st.change = +(st.price - st.prevClose).toFixed(2);\n                        st.changePct = st.prevClose ? +((st.change / st.prevClose) * 100).toFixed(2) : 0;\n                        st.volume = last.volume || st.volume;\n\n                        if (!resolved) {\n                          resolved = true;\n                          clearTimeout(timer);\n                          document.getElementById(\'tv-api-status-pill\').textContent = `WS (${bars.length})`;\n                          renderAll();\n                          showToast(`Loaded ${bars.length} real ${tf} bars for NSEKE:${ticker} from TradingView WebSocket.`);\n                          resolve(true);\n                        } else {\n                          renderChart();\n                        }\n                      }\n                    }\n                  }\n                } catch (_) {}\n              }\n            };\n\n            ws.onerror = () => {\n              if (!resolved) {\n                resolved = true;\n                clearTimeout(timer);\n                resolve(false);\n              }\n            };\n          } catch (_) {\n            resolve(false);\n          }\n        });\n      },\n\n      connectLocalWsBridge(url) {\n        try {\n          if (this.ws) this.ws.close();\n          const ws = new WebSocket(url);\n          this.ws = ws;\n          ws.onopen = () => {\n            document.getElementById(\'tv-api-status-pill\').textContent = \'LOCAL WS\';\n            showToast(`Connected to local TradingView bridge at ${url}`);\n            this.requestFromLocalBridge(state.selectedTicker, state.timeframe);\n          };\n          ws.onmessage = (evt) => {\n            try {\n              const msg = JSON.parse(evt.data);\n              if (msg.type === \'history\' && Array.isArray(msg.bars) && msg.bars.length > 0) {\n                const sym = (msg.symbol || state.selectedTicker).replace(\'NSEKE:\', \'\');\n                state.historyCache[`${sym}_${state.timeframe}`] = msg.bars;\n                const last = msg.bars[msg.bars.length - 1];\n                let st = state.stocks.find(s => s.ticker === sym);\n                if (!st) {\n                  st = { ticker: sym, name: sym, price: last.close, open: last.open, high: last.high, low: last.low, prevClose: last.open, change: 0, changePct: 0, volume: last.volume || 0 };\n                  state.stocks.unshift(st);\n                }\n                st.price = last.close;\n                st.open = last.open;\n                st.high = last.high;\n                st.low = last.low;\n                renderAll();\n                showToast(`Received ${msg.bars.length} real OHLCV bars for ${sym}.`);\n              }\n            } catch (_) {}\n          };\n          ws.onerror = () => showToast(`Could not connect to ${url}. Ensure local server is running.`);\n        } catch (_) {}\n      },\n\n      requestFromLocalBridge(ticker, tf) {\n        if (this.ws && this.ws.readyState === WebSocket.OPEN) {\n          const tfMap = { \'1m\': \'1\', \'5m\': \'5\', \'15m\': \'15\', \'1H\': \'60\', \'1D\': \'D\', \'1W\': \'W\', \'1M\': \'M\' };\n          this.ws.send(JSON.stringify({ symbol: `NSEKE:${ticker}`, timeframe: tfMap[tf] || \'D\', range: 2000 }));\n        }\n      },\n\n      async fetchLocalRestBridge(baseUrl) {\n        try {\n          if (!baseUrl) {\n            await this.scrapeAllNseSymbols();\n            await this.fetchDirectTradingViewWs(state.selectedTicker, state.timeframe, 500);\n            return;\n          }\n          const clean = baseUrl.replace(/\\/$/, \'\');\n          await this.scrapeAllNseSymbols();\n          const url = `${clean}/api/history?symbol=${encodeURIComponent(state.selectedTicker)}&tf=${encodeURIComponent(state.timeframe)}&bars=1500`;\n          const res = await fetch(url);\n          if (!res.ok) throw new Error(\'HTTP \' + res.status);\n          const json = await res.json();\n          const bars = Array.isArray(json) ? json : json.bars;\n          if (Array.isArray(bars) && bars.length > 0) {\n            state.historyCache[`${state.selectedTicker}_${state.timeframe}`] = bars;\n            renderAll();\n            showToast(`Loaded ${bars.length} real bars from cloud API endpoint.`);\n          }\n        } catch (err) {\n          showToast(`Cloud API fetch failed: ${err.message}`);\n        }\n      }\n    };\n\n    function getActiveBars() {\n      const key = `${state.selectedTicker}_${state.timeframe}`;\n      if (state.historyCache[key] && state.historyCache[key].length > 0) {\n        return state.historyCache[key];\n      }\n      // If scanner returned live daily OHLC for this symbol, show that single verified session bar\n      const st = state.stocks.find(s => s.ticker === state.selectedTicker);\n      if (st && st.price > 0) {\n        return [{\n          date: \'LATEST SESSION\',\n          open: st.open || st.price,\n          high: st.high || st.price,\n          low: st.low || st.price,\n          close: st.price,\n          volume: st.volume || 0\n        }];\n      }\n      return [];\n    }\n\n    // =========================================================================\n    // TECHNICAL INDICATORS (SMA 20, EMA 50, BOLLINGER BANDS 20,2)\n    // =========================================================================\n    function computeSMA(bars, period) {\n      return bars.map((_, i) => {\n        if (i < period - 1) return null;\n        let sum = 0;\n        for (let j = 0; j < period; j++) sum += bars[i - j].close;\n        return sum / period;\n      });\n    }\n\n    function computeEMA(bars, period) {\n      const k = 2 / (period + 1);\n      const out = [];\n      let prev = null;\n      for (let i = 0; i < bars.length; i++) {\n        const c = bars[i].close;\n        prev = prev === null ? c : c * k + prev * (1 - k);\n        out.push(prev);\n      }\n      return out;\n    }\n\n    function computeBollinger(bars, period = 20, mult = 2) {\n      const sma = computeSMA(bars, period);\n      return bars.map((_, i) => {\n        if (sma[i] === null) return null;\n        let sq = 0;\n        for (let j = 0; j < period; j++) {\n          const diff = bars[i - j].close - sma[i];\n          sq += diff * diff;\n        }\n        const std = Math.sqrt(sq / period);\n        return { upper: sma[i] + mult * std, mid: sma[i], lower: sma[i] - mult * std };\n      });\n    }\n\n    // =========================================================================\n    // INTERACTIVE HIGH-DPI CHART ENGINE WITH SCROLLABLE/ZOOMABLE X & Y SCALES\n    // =========================================================================\n    let chartGeometry = null;\n\n    function renderChart() {\n      const container = document.getElementById(\'chart-container\');\n      const canvas = document.getElementById(\'main-chart-canvas\');\n      const overlay = document.getElementById(\'chart-empty-overlay\');\n      const bars = getActiveBars();\n\n      document.getElementById(\'bar-count-label\').textContent = bars.length;\n\n      if (bars.length === 0) {\n        overlay.classList.remove(\'hidden\');\n        return;\n      }\n      overlay.classList.add(\'hidden\');\n\n      const dpr = window.devicePixelRatio || 1;\n      const rect = container.getBoundingClientRect();\n      const width = Math.max(300, Math.floor(rect.width));\n      const height = Math.max(300, Math.floor(rect.height));\n\n      if (canvas.width !== width * dpr || canvas.height !== height * dpr) {\n        canvas.width = width * dpr;\n        canvas.height = height * dpr;\n      }\n\n      const ctx = canvas.getContext(\'2d\');\n      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n      ctx.fillStyle = \'#000000\';\n      ctx.fillRect(0, 0, width, height);\n\n      const padLeft = 10;\n      const padRight = 68;  // Interactive Y-Axis Price Scale strip\n      const padTop = 16;\n      const padBottom = 26; // Interactive X-Axis Time Scale strip\n      const plotW = width - padLeft - padRight;\n      const plotH = height - padTop - padBottom;\n      const volH = state.indicators.vol ? Math.floor(plotH * 0.18) : 0;\n      const priceH = plotH - volH;\n\n      // Clamp horizontal X-scale viewport\n      const maxVisible = Math.max(10, Math.min(bars.length, state.viewport.visibleBars));\n      const maxOffset = Math.max(0, bars.length - maxVisible);\n      state.viewport.rightOffset = Math.max(0, Math.min(maxOffset, state.viewport.rightOffset));\n\n      const endIdx = bars.length - state.viewport.rightOffset;\n      const startIdx = Math.max(0, endIdx - maxVisible);\n      const visible = bars.slice(startIdx, endIdx);\n\n      // Compute Base Min/Max Price then apply Interactive Y-Axis Scale & Pan\n      let rawMin = Infinity;\n      let rawMax = -Infinity;\n      let maxVol = 0;\n      for (const b of visible) {\n        if (b.low < rawMin) rawMin = b.low;\n        if (b.high > rawMax) rawMax = b.high;\n        if (b.volume > maxVol) maxVol = b.volume;\n      }\n      if (!isFinite(rawMin) || !isFinite(rawMax)) {\n        rawMin = 0;\n        rawMax = 100;\n      }\n      const baseRange = Math.max(0.05, rawMax - rawMin);\n      const midPrice = (rawMax + rawMin) / 2 + state.viewport.yPanOffset;\n      const scaledHalfRange = (baseRange * 0.58) * state.viewport.yZoom;\n      const minPrice = midPrice - scaledHalfRange;\n      const maxPrice = midPrice + scaledHalfRange;\n      const priceRange = Math.max(0.01, maxPrice - minPrice);\n\n      const priceToY = (p) => padTop + ((maxPrice - p) / priceRange) * priceH;\n      const yToPrice = (y) => maxPrice - ((y - padTop) / priceH) * priceRange;\n      const stepX = plotW / Math.max(1, visible.length);\n      const indexToX = (localIdx) => padLeft + (localIdx + 0.5) * stepX;\n\n      chartGeometry = {\n        width, height, padLeft, padRight, padTop, padBottom,\n        plotW, plotH, priceH, startIdx, endIdx, visible,\n        minPrice, maxPrice, priceToY, yToPrice, stepX, indexToX\n      };\n\n      document.getElementById(\'y-scale-readout\').textContent =\n        state.viewport.yZoom === 1 && state.viewport.yPanOffset === 0\n          ? \'AUTO (100%)\'\n          : `${Math.round((1 / state.viewport.yZoom) * 100)}%`;\n\n      // 1. Grid Lines & Y-Axis Price Scale Labels\n      ctx.strokeStyle = \'#161616\';\n      ctx.lineWidth = 1;\n      ctx.font = \'11px "JetBrains Mono", monospace\';\n      ctx.textAlign = \'left\';\n      ctx.textBaseline = \'middle\';\n\n      const yTicks = 7;\n      for (let i = 0; i <= yTicks; i++) {\n        const y = padTop + (priceH / yTicks) * i;\n        const val = maxPrice - (priceRange / yTicks) * i;\n        ctx.beginPath();\n        ctx.moveTo(padLeft, Math.round(y) + 0.5);\n        ctx.lineTo(width - padRight, Math.round(y) + 0.5);\n        ctx.stroke();\n\n        ctx.fillStyle = \'#8c8c8c\';\n        ctx.fillText(val.toFixed(2), width - padRight + 6, y);\n      }\n\n      // 2. X-Axis Time Scale Labels\n      const xTickStep = Math.max(1, Math.floor(visible.length / 6));\n      ctx.textAlign = \'center\';\n      ctx.textBaseline = \'top\';\n      for (let i = 0; i < visible.length; i += xTickStep) {\n        const x = indexToX(i);\n        ctx.strokeStyle = \'#161616\';\n        ctx.beginPath();\n        ctx.moveTo(Math.round(x) + 0.5, padTop);\n        ctx.lineTo(Math.round(x) + 0.5, height - padBottom);\n        ctx.stroke();\n\n        ctx.fillStyle = \'#8c8c8c\';\n        ctx.fillText(visible[i].date, x, height - padBottom + 6);\n      }\n\n      // 3. Volume Histogram\n      if (state.indicators.vol && maxVol > 0) {\n        for (let i = 0; i < visible.length; i++) {\n          const b = visible[i];\n          const x = indexToX(i);\n          const barW = Math.max(1, stepX * 0.65);\n          const h = (b.volume / maxVol) * (volH - 4);\n          ctx.fillStyle = b.close >= b.open ? \'rgba(8, 153, 129, 0.35)\' : \'rgba(242, 54, 69, 0.35)\';\n          ctx.fillRect(x - barW / 2, padTop + plotH - h, barW, h);\n        }\n      }\n\n      // 4. Technical Indicators (Bollinger Bands, SMA 20, EMA 50)\n      const fullSma20 = state.indicators.sma20 ? computeSMA(bars, 20) : null;\n      const fullEma50 = state.indicators.ema50 ? computeEMA(bars, 50) : null;\n      const fullBb = state.indicators.bb ? computeBollinger(bars, 20, 2) : null;\n\n      if (fullBb) {\n        ctx.strokeStyle = \'rgba(255, 255, 255, 0.35)\';\n        ctx.lineWidth = 1;\n        [\'upper\', \'lower\'].forEach(band => {\n          ctx.beginPath();\n          let started = false;\n          for (let i = 0; i < visible.length; i++) {\n            const item = fullBb[startIdx + i];\n            if (!item) continue;\n            const x = indexToX(i);\n            const y = priceToY(item[band]);\n            if (!started) { ctx.moveTo(x, y); started = true; }\n            else ctx.lineTo(x, y);\n          }\n          ctx.stroke();\n        });\n      }\n\n      if (fullSma20) {\n        ctx.strokeStyle = \'#ffffff\';\n        ctx.lineWidth = 1.25;\n        ctx.beginPath();\n        let started = false;\n        for (let i = 0; i < visible.length; i++) {\n          const val = fullSma20[startIdx + i];\n          if (val === null) continue;\n          const x = indexToX(i);\n          const y = priceToY(val);\n          if (!started) { ctx.moveTo(x, y); started = true; }\n          else ctx.lineTo(x, y);\n        }\n        ctx.stroke();\n      }\n\n      if (fullEma50) {\n        ctx.strokeStyle = \'#8c8c8c\';\n        ctx.lineWidth = 1.25;\n        ctx.setLineDash([4, 3]);\n        ctx.beginPath();\n        for (let i = 0; i < visible.length; i++) {\n          const x = indexToX(i);\n          const y = priceToY(fullEma50[startIdx + i]);\n          if (i === 0) ctx.moveTo(x, y);\n          else ctx.lineTo(x, y);\n        }\n        ctx.stroke();\n        ctx.setLineDash([]);\n      }\n\n      // 5. Price Series (Candles, Hollow, OHLC Bars, or Line)\n      const candleW = Math.max(2, Math.min(18, stepX * 0.68));\n      if (state.chartStyle === \'line\') {\n        ctx.strokeStyle = \'#ffffff\';\n        ctx.lineWidth = 1.75;\n        ctx.beginPath();\n        for (let i = 0; i < visible.length; i++) {\n          const x = indexToX(i);\n          const y = priceToY(visible[i].close);\n          if (i === 0) ctx.moveTo(x, y);\n          else ctx.lineTo(x, y);\n        }\n        ctx.stroke();\n      } else {\n        for (let i = 0; i < visible.length; i++) {\n          const b = visible[i];\n          const x = indexToX(i);\n          const isBull = b.close >= b.open;\n          const color = isBull ? \'#089981\' : \'#f23645\';\n          const yHigh = priceToY(b.high);\n          const yLow = priceToY(b.low);\n          const yOpen = priceToY(b.open);\n          const yClose = priceToY(b.close);\n\n          ctx.strokeStyle = color;\n          ctx.fillStyle = color;\n          ctx.lineWidth = 1;\n\n          // Wick\n          ctx.beginPath();\n          ctx.moveTo(Math.round(x) + 0.5, yHigh);\n          ctx.lineTo(Math.round(x) + 0.5, yLow);\n          ctx.stroke();\n\n          if (state.chartStyle === \'ohlc\') {\n            const tick = Math.max(2, candleW * 0.5);\n            ctx.beginPath();\n            ctx.moveTo(x - tick, yOpen);\n            ctx.lineTo(x, yOpen);\n            ctx.moveTo(x, yClose);\n            ctx.lineTo(x + tick, yClose);\n            ctx.stroke();\n          } else {\n            const top = Math.min(yOpen, yClose);\n            const bodyH = Math.max(1.5, Math.abs(yClose - yOpen));\n            if (state.chartStyle === \'hollow\' && isBull) {\n              ctx.strokeRect(x - candleW / 2, top, candleW, bodyH);\n            } else {\n              ctx.fillRect(x - candleW / 2, top, candleW, bodyH);\n            }\n          }\n        }\n      }\n\n      // 6. User Drawings (Trendline, HLine, Fib, Rect)\n      const list = [...(state.drawings[state.selectedTicker] || [])];\n      if (state.activeDraft) list.push(state.activeDraft);\n\n      for (const d of list) {\n        ctx.strokeStyle = \'#ffffff\';\n        ctx.lineWidth = 1;\n        const y1 = priceToY(d.p1);\n        const y2 = priceToY(d.p2);\n        const x1 = indexToX(d.i1 - startIdx);\n        const x2 = indexToX(d.i2 - startIdx);\n\n        if (d.type === \'hline\') {\n          ctx.setLineDash([4, 4]);\n          ctx.beginPath();\n          ctx.moveTo(padLeft, y1);\n          ctx.lineTo(width - padRight, y1);\n          ctx.stroke();\n          ctx.setLineDash([]);\n        } else if (d.type === \'trendline\') {\n          ctx.beginPath();\n          ctx.moveTo(x1, y1);\n          ctx.lineTo(x2, y2);\n          ctx.stroke();\n        } else if (d.type === \'rect\') {\n          ctx.fillStyle = \'rgba(255,255,255,0.08)\';\n          ctx.fillRect(Math.min(x1, x2), Math.min(y1, y2), Math.abs(x2 - x1), Math.abs(y2 - y1));\n          ctx.strokeRect(Math.min(x1, x2), Math.min(y1, y2), Math.abs(x2 - x1), Math.abs(y2 - y1));\n        } else if (d.type === \'fib\') {\n          const levels = [0, 0.236, 0.382, 0.5, 0.618, 0.786, 1];\n          const left = Math.min(x1, x2);\n          const right = Math.max(x1, x2, left + 80);\n          levels.forEach(lvl => {\n            const p = d.p1 + (d.p2 - d.p1) * lvl;\n            const y = priceToY(p);\n            ctx.beginPath();\n            ctx.moveTo(left, y);\n            ctx.lineTo(right, y);\n            ctx.stroke();\n            ctx.fillStyle = \'#ffffff\';\n            ctx.font = \'10px "JetBrains Mono", monospace\';\n            ctx.textAlign = \'left\';\n            ctx.fillText(`${(lvl * 100).toFixed(1)}% (${p.toFixed(2)})`, left + 4, y - 8);\n          });\n        }\n      }\n\n      // 7. Interactive Y-Axis & X-Axis Borders + Last Price Tag\n      ctx.strokeStyle = \'#262626\';\n      ctx.lineWidth = 1;\n      ctx.beginPath();\n      ctx.moveTo(width - padRight + 0.5, 0);\n      ctx.lineTo(width - padRight + 0.5, height);\n      ctx.moveTo(0, height - padBottom + 0.5);\n      ctx.lineTo(width, height - padBottom + 0.5);\n      ctx.stroke();\n\n      const lastBar = visible[visible.length - 1];\n      if (lastBar) {\n        const lastY = Math.max(padTop, Math.min(padTop + priceH, priceToY(lastBar.close)));\n        const isBull = lastBar.close >= lastBar.open;\n        ctx.strokeStyle = isBull ? \'#089981\' : \'#f23645\';\n        ctx.setLineDash([2, 2]);\n        ctx.beginPath();\n        ctx.moveTo(padLeft, lastY);\n        ctx.lineTo(width - padRight, lastY);\n        ctx.stroke();\n        ctx.setLineDash([]);\n\n        ctx.fillStyle = isBull ? \'#089981\' : \'#f23645\';\n        ctx.fillRect(width - padRight, lastY - 9, padRight, 18);\n        ctx.fillStyle = \'#ffffff\';\n        ctx.font = \'bold 11px "JetBrains Mono", monospace\';\n        ctx.textAlign = \'left\';\n        ctx.textBaseline = \'middle\';\n        ctx.fillText(lastBar.close.toFixed(2), width - padRight + 6, lastY);\n      }\n\n      // 8. Crosshair & Hover OHLC Readout\n      let hoveredBar = lastBar;\n      if (state.pointer.inside && state.pointer.x < width - padRight && state.pointer.y < height - padBottom) {\n        const mx = state.pointer.x;\n        const my = state.pointer.y;\n        const localIdx = Math.max(0, Math.min(visible.length - 1, Math.floor((mx - padLeft) / stepX)));\n        hoveredBar = visible[localIdx] || lastBar;\n        const snapX = indexToX(localIdx);\n\n        ctx.strokeStyle = \'rgba(255, 255, 255, 0.35)\';\n        ctx.setLineDash([3, 3]);\n        ctx.beginPath();\n        ctx.moveTo(snapX, padTop);\n        ctx.lineTo(snapX, height - padBottom);\n        ctx.moveTo(padLeft, my);\n        ctx.lineTo(width - padRight, my);\n        ctx.stroke();\n        ctx.setLineDash([]);\n\n        // Y-Axis Crosshair Badge\n        const hoverPrice = yToPrice(my);\n        ctx.fillStyle = \'#ffffff\';\n        ctx.fillRect(width - padRight, my - 9, padRight, 18);\n        ctx.fillStyle = \'#000000\';\n        ctx.font = \'bold 11px "JetBrains Mono", monospace\';\n        ctx.textAlign = \'left\';\n        ctx.textBaseline = \'middle\';\n        ctx.fillText(hoverPrice.toFixed(2), width - padRight + 6, my);\n\n        // X-Axis Crosshair Date Badge\n        ctx.fillStyle = \'#ffffff\';\n        const dateW = 92;\n        ctx.fillRect(snapX - dateW / 2, height - padBottom + 1, dateW, padBottom - 2);\n        ctx.fillStyle = \'#000000\';\n        ctx.textAlign = \'center\';\n        ctx.textBaseline = \'middle\';\n        ctx.fillText(hoveredBar.date, snapX, height - padBottom / 2);\n      }\n\n      if (hoveredBar) {\n        const chg = hoveredBar.close - hoveredBar.open;\n        const chgPct = hoveredBar.open ? (chg / hoveredBar.open) * 100 : 0;\n        document.getElementById(\'ohlc-o\').textContent = hoveredBar.open.toFixed(2);\n        document.getElementById(\'ohlc-h\').textContent = hoveredBar.high.toFixed(2);\n        document.getElementById(\'ohlc-l\').textContent = hoveredBar.low.toFixed(2);\n        document.getElementById(\'ohlc-c\').textContent = hoveredBar.close.toFixed(2);\n        document.getElementById(\'ohlc-v\').textContent = hoveredBar.volume.toLocaleString();\n        const chgEl = document.getElementById(\'ohlc-chg\');\n        chgEl.textContent = `${chg >= 0 ? \'+\' : \'\'}${chg.toFixed(2)} (${chgPct >= 0 ? \'+\' : \'\'}${chgPct.toFixed(2)}%)`;\n        chgEl.className = `font-semibold ${chg >= 0 ? \'text-nse-green\' : \'text-nse-red\'}`;\n      }\n    }\n\n    // =========================================================================\n    // INTERACTIVE X & Y SCALE MOUSE / WHEEL / TOUCH HANDLERS\n    // =========================================================================\n    function bindChartScaleInteractions() {\n      const canvas = document.getElementById(\'main-chart-canvas\');\n\n      canvas.addEventListener(\'mousemove\', (e) => {\n        if (!chartGeometry) return;\n        const rect = canvas.getBoundingClientRect();\n        const x = e.clientX - rect.left;\n        const y = e.clientY - rect.top;\n        state.pointer.inside = true;\n        state.pointer.x = x;\n        state.pointer.y = y;\n\n        const onYAxis = x >= chartGeometry.width - chartGeometry.padRight;\n        const onXAxis = y >= chartGeometry.height - chartGeometry.padBottom;\n\n        if (!state.pointer.dragMode) {\n          if (onYAxis) canvas.style.cursor = \'ns-resize\';\n          else if (onXAxis) canvas.style.cursor = \'ew-resize\';\n          else canvas.style.cursor = state.activeTool === \'crosshair\' ? \'crosshair\' : \'cell\';\n        }\n\n        if (state.pointer.dragMode === \'scale-y\') {\n          // Dragging up on Y-axis zooms in (smaller yZoom), dragging down zooms out\n          const dy = y - state.pointer.dragStartY;\n          const factor = Math.exp(dy * 0.006);\n          state.viewport.yZoom = Math.max(0.15, Math.min(8.0, state.pointer.startYZoom * factor));\n        } else if (state.pointer.dragMode === \'scale-x\') {\n          // Dragging right on X-axis expands candles (zooms in), dragging left compresses (zooms out)\n          const dx = x - state.pointer.dragStartX;\n          const factor = Math.exp(-dx * 0.005);\n          state.viewport.visibleBars = Math.max(10, Math.min(1000, Math.round(state.pointer.startVisibleBars * factor)));\n        } else if (state.pointer.dragMode === \'pan-xy\') {\n          const dx = x - state.pointer.dragStartX;\n          const dy = y - state.pointer.dragStartY;\n          const barShift = Math.round(dx / Math.max(2, chartGeometry.stepX));\n          state.viewport.rightOffset = state.pointer.startRightOffset + barShift;\n\n          const pricePerPx = (chartGeometry.maxPrice - chartGeometry.minPrice) / Math.max(1, chartGeometry.priceH);\n          state.viewport.yPanOffset = state.pointer.startYPanOffset + dy * pricePerPx;\n        } else if (state.pointer.dragMode === \'draw\' && state.activeDraft) {\n          const localIdx = Math.max(0, Math.min(chartGeometry.visible.length - 1, Math.floor((x - chartGeometry.padLeft) / chartGeometry.stepX)));\n          state.activeDraft.i2 = chartGeometry.startIdx + localIdx;\n          state.activeDraft.p2 = chartGeometry.yToPrice(y);\n        }\n\n        renderChart();\n      });\n\n      canvas.addEventListener(\'mouseleave\', () => {\n        state.pointer.inside = false;\n        state.pointer.dragMode = null;\n        renderChart();\n      });\n\n      canvas.addEventListener(\'mousedown\', (e) => {\n        if (!chartGeometry) return;\n        const rect = canvas.getBoundingClientRect();\n        const x = e.clientX - rect.left;\n        const y = e.clientY - rect.top;\n\n        state.pointer.dragStartX = x;\n        state.pointer.dragStartY = y;\n        state.pointer.startRightOffset = state.viewport.rightOffset;\n        state.pointer.startVisibleBars = state.viewport.visibleBars;\n        state.pointer.startYZoom = state.viewport.yZoom;\n        state.pointer.startYPanOffset = state.viewport.yPanOffset;\n\n        const onYAxis = x >= chartGeometry.width - chartGeometry.padRight;\n        const onXAxis = y >= chartGeometry.height - chartGeometry.padBottom;\n\n        if (onYAxis) {\n          state.pointer.dragMode = \'scale-y\';\n        } else if (onXAxis) {\n          state.pointer.dragMode = \'scale-x\';\n        } else if (state.activeTool !== \'crosshair\') {\n          const localIdx = Math.max(0, Math.min(chartGeometry.visible.length - 1, Math.floor((x - chartGeometry.padLeft) / chartGeometry.stepX)));\n          const barIdx = chartGeometry.startIdx + localIdx;\n          const price = chartGeometry.yToPrice(y);\n          if (state.activeTool === \'hline\') {\n            if (!state.drawings[state.selectedTicker]) state.drawings[state.selectedTicker] = [];\n            state.drawings[state.selectedTicker].push({ type: \'hline\', i1: barIdx, p1: price, i2: barIdx, p2: price });\n            renderChart();\n          } else {\n            state.pointer.dragMode = \'draw\';\n            state.activeDraft = { type: state.activeTool, i1: barIdx, p1: price, i2: barIdx, p2: price };\n          }\n        } else {\n          state.pointer.dragMode = \'pan-xy\';\n          canvas.style.cursor = \'grabbing\';\n        }\n      });\n\n      window.addEventListener(\'mouseup\', () => {\n        if (state.pointer.dragMode === \'draw\' && state.activeDraft) {\n          if (!state.drawings[state.selectedTicker]) state.drawings[state.selectedTicker] = [];\n          state.drawings[state.selectedTicker].push(state.activeDraft);\n          state.activeDraft = null;\n        }\n        state.pointer.dragMode = null;\n        renderChart();\n      });\n\n      // Double-click on Y-Axis resets Y scale; double-click on X-Axis resets X scale\n      canvas.addEventListener(\'dblclick\', (e) => {\n        if (!chartGeometry) return;\n        const rect = canvas.getBoundingClientRect();\n        const x = e.clientX - rect.left;\n        const y = e.clientY - rect.top;\n        if (x >= chartGeometry.width - chartGeometry.padRight) {\n          state.viewport.yZoom = 1.0;\n          state.viewport.yPanOffset = 0;\n          showToast(\'Y-Axis Price Scale reset to Auto.\');\n        } else if (y >= chartGeometry.height - chartGeometry.padBottom) {\n          state.viewport.visibleBars = 90;\n          state.viewport.rightOffset = 0;\n          showToast(\'X-Axis Time Scale reset.\');\n        } else {\n          state.viewport.yZoom = 1.0;\n          state.viewport.yPanOffset = 0;\n          state.viewport.visibleBars = 90;\n          state.viewport.rightOffset = 0;\n        }\n        renderChart();\n      });\n\n      // Mouse Wheel: Scroll over Y-axis scales Y; Shift+Wheel scrolls X-axis horizontally; normal Wheel zooms X-axis\n      canvas.addEventListener(\'wheel\', (e) => {\n        if (!chartGeometry) return;\n        e.preventDefault();\n        const rect = canvas.getBoundingClientRect();\n        const x = e.clientX - rect.left;\n        const onYAxis = x >= chartGeometry.width - chartGeometry.padRight;\n\n        if (onYAxis) {\n          const factor = e.deltaY > 0 ? 1.12 : 0.88;\n          state.viewport.yZoom = Math.max(0.15, Math.min(8.0, state.viewport.yZoom * factor));\n        } else if (e.shiftKey || Math.abs(e.deltaX) > Math.abs(e.deltaY)) {\n          const delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;\n          const step = Math.max(1, Math.round(state.viewport.visibleBars * 0.08));\n          state.viewport.rightOffset += delta > 0 ? -step : step;\n        } else {\n          const factor = e.deltaY > 0 ? 1.12 : 0.88;\n          state.viewport.visibleBars = Math.max(10, Math.min(1000, Math.round(state.viewport.visibleBars * factor)));\n        }\n        renderChart();\n      }, { passive: false });\n    }\n\n    // =========================================================================\n    // WATCHLIST, SCREENER & UI RENDERERS\n    // =========================================================================\n    function renderWatchlist() {\n      const body = document.getElementById(\'watchlist-body\');\n      const q = state.searchQuery.trim().toLowerCase();\n      const filtered = state.stocks.filter(s =>\n        !q || s.ticker.toLowerCase().includes(q) || (s.name && s.name.toLowerCase().includes(q))\n      );\n\n      document.getElementById(\'watchlist-count\').textContent = `${filtered.length} SYMBOLS`;\n      document.getElementById(\'symbol-count-badge\').textContent = state.stocks.length;\n\n      if (filtered.length === 0) {\n        body.innerHTML = `<div class="p-4 text-xs font-mono text-nse-muted text-center">No scraped NSEKE symbols loaded yet. Click "SCRAPE TRADINGVIEW" or "IMPORT CSV".</div>`;\n        return;\n      }\n\n      body.innerHTML = filtered.map(s => {\n        const active = s.ticker === state.selectedTicker;\n        const chgClass = s.changePct > 0 ? \'text-nse-green\' : s.changePct < 0 ? \'text-nse-red\' : \'text-nse-muted\';\n        return `\n          <button data-ticker="${s.ticker}" class="watch-row w-full grid grid-cols-12 items-center px-2 py-1.5 text-left font-mono text-xs tabular-nums ${active ? \'bg-white text-black font-bold\' : \'hover:bg-nse-hover text-white\'}">\n            <div class="col-span-5 truncate">\n              <div>${s.ticker}</div>\n              <div class="text-[10px] truncate ${active ? \'text-black/70\' : \'text-nse-muted\'}">${s.name}</div>\n            </div>\n            <div class="col-span-4 text-right">${s.price.toFixed(2)}</div>\n            <div class="col-span-3 text-right ${active ? \'text-black\' : chgClass}">${s.changePct >= 0 ? \'+\' : \'\'}${s.changePct.toFixed(2)}%</div>\n          </button>\n        `;\n      }).join(\'\');\n\n      body.querySelectorAll(\'.watch-row\').forEach(btn => {\n        btn.addEventListener(\'click\', () => {\n          state.selectedTicker = btn.dataset.ticker;\n          state.viewport.rightOffset = 0;\n          state.viewport.yZoom = 1.0;\n          state.viewport.yPanOffset = 0;\n          tvScraper.fetchDirectTradingViewWs(state.selectedTicker, state.timeframe, 500);\n          tvScraper.requestFromLocalBridge(state.selectedTicker, state.timeframe);\n          renderAll();\n        });\n      });\n    }\n\n    function renderSelectedDetail() {\n      const s = state.stocks.find(item => item.ticker === state.selectedTicker);\n      const badge = document.getElementById(\'chart-symbol-badge\');\n      const link = document.getElementById(\'tv-external-link\');\n      badge.textContent = `NSEKE:${state.selectedTicker}`;\n      link.href = `https://www.tradingview.com/chart/IInGcnS5/?symbol=NSEKE%3A${encodeURIComponent(state.selectedTicker)}`;\n\n      if (!s) {\n        document.getElementById(\'chart-company-name\').textContent = state.selectedTicker;\n        document.getElementById(\'detail-ticker\').textContent = `NSEKE:${state.selectedTicker}`;\n        return;\n      }\n\n      document.getElementById(\'chart-company-name\').textContent = s.name;\n      document.getElementById(\'detail-ticker\').textContent = `NSEKE:${s.ticker}`;\n      document.getElementById(\'detail-name\').textContent = s.name;\n      document.getElementById(\'detail-price\').textContent = `KES ${s.price.toFixed(2)}`;\n      const chgEl = document.getElementById(\'detail-change\');\n      chgEl.textContent = `${s.change >= 0 ? \'+\' : \'\'}${s.change.toFixed(2)} (${s.changePct >= 0 ? \'+\' : \'\'}${s.changePct.toFixed(2)}%)`;\n      chgEl.className = `text-[11px] ${s.changePct >= 0 ? \'text-nse-green\' : \'text-nse-red\'}`;\n\n      document.getElementById(\'detail-open\').textContent = s.open != null ? s.open.toFixed(2) : \'--\';\n      document.getElementById(\'detail-prev\').textContent = s.prevClose != null ? s.prevClose.toFixed(2) : \'--\';\n      document.getElementById(\'detail-high\').textContent = s.high != null ? s.high.toFixed(2) : \'--\';\n      document.getElementById(\'detail-low\').textContent = s.low != null ? s.low.toFixed(2) : \'--\';\n      document.getElementById(\'detail-52h\').textContent = s.high52 != null ? s.high52.toFixed(2) : \'--\';\n      document.getElementById(\'detail-52l\').textContent = s.low52 != null ? s.low52.toFixed(2) : \'--\';\n      document.getElementById(\'detail-vol\').textContent = s.volume != null ? s.volume.toLocaleString() : \'--\';\n      document.getElementById(\'detail-rsi\').textContent = s.rsi != null ? s.rsi.toFixed(1) : \'--\';\n    }\n\n    function renderScreenerTable() {\n      const tbody = document.getElementById(\'screener-table-body\');\n      if (state.stocks.length === 0) {\n        tbody.innerHTML = `<tr><td colspan="13" class="p-4 text-center text-nse-muted">No symbols scraped yet. Click "Refresh All NSEKE Symbols".</td></tr>`;\n        return;\n      }\n      tbody.innerHTML = state.stocks.map(s => {\n        const chgClass = s.changePct > 0 ? \'text-nse-green\' : s.changePct < 0 ? \'text-nse-red\' : \'text-nse-muted\';\n        const fmt = (v) => v != null ? `${v >= 0 ? \'+\' : \'\'}${v.toFixed(2)}%` : \'--\';\n        return `\n          <tr data-ticker="${s.ticker}" class="screener-row hover:bg-nse-hover cursor-pointer">\n            <td class="p-2 font-bold text-white">${s.ticker}</td>\n            <td class="p-2 text-nse-muted">${s.name}</td>\n            <td class="p-2 text-right font-bold">${s.price.toFixed(2)}</td>\n            <td class="p-2 text-right ${chgClass}">${fmt(s.changePct)}</td>\n            <td class="p-2 text-right">${s.open.toFixed(2)}</td>\n            <td class="p-2 text-right">${s.high.toFixed(2)}</td>\n            <td class="p-2 text-right">${s.low.toFixed(2)}</td>\n            <td class="p-2 text-right">${s.volume.toLocaleString()}</td>\n            <td class="p-2 text-right">${fmt(s.perfW)}</td>\n            <td class="p-2 text-right">${fmt(s.perf1M)}</td>\n            <td class="p-2 text-right">${fmt(s.perf1Y)}</td>\n            <td class="p-2 text-right">${s.high52 != null ? s.high52.toFixed(2) : \'--\'}</td>\n            <td class="p-2 text-right">${s.low52 != null ? s.low52.toFixed(2) : \'--\'}</td>\n          </tr>\n        `;\n      }).join(\'\');\n\n      tbody.querySelectorAll(\'.screener-row\').forEach(tr => {\n        tr.addEventListener(\'click\', () => {\n          state.selectedTicker = tr.dataset.ticker;\n          switchWorkspace(\'charts\');\n          tvScraper.fetchDirectTradingViewWs(state.selectedTicker, state.timeframe, 500);\n          renderAll();\n        });\n      });\n    }\n\n    function renderAll() {\n      renderWatchlist();\n      renderSelectedDetail();\n      renderChart();\n      if (!document.getElementById(\'workspace-screener\').classList.contains(\'hidden\')) {\n        renderScreenerTable();\n      }\n    }\n\n    function switchWorkspace(target) {\n      [\'charts\', \'screener\', \'connectors\'].forEach(ws => {\n        document.getElementById(`workspace-${ws}`).classList.toggle(\'hidden\', ws !== target);\n        document.getElementById(`ws-btn-${ws}`).classList.toggle(\'active\', ws === target);\n      });\n      if (target === \'charts\') renderChart();\n      if (target === \'screener\') renderScreenerTable();\n    }\n\n    // =========================================================================\n    // CSV PARSER & EVENT BINDINGS\n    // =========================================================================\n    function parseCsvAndLoad(rawText) {\n      const lines = rawText.trim().split(/\\r?\\n/).filter(Boolean);\n      const bars = [];\n      for (const line of lines) {\n        const parts = line.split(\',\').map(p => p.trim());\n        if (parts.length < 5) continue;\n        const o = parseFloat(parts[1]);\n        const h = parseFloat(parts[2]);\n        const l = parseFloat(parts[3]);\n        const c = parseFloat(parts[4]);\n        const v = parseFloat(parts[5] || \'0\');\n        if (isNaN(o) || isNaN(h) || isNaN(l) || isNaN(c)) continue;\n        bars.push({ date: parts[0], open: o, high: h, low: l, close: c, volume: Math.round(v) });\n      }\n      if (bars.length > 0) {\n        state.historyCache[`${state.selectedTicker}_${state.timeframe}`] = bars;\n        const last = bars[bars.length - 1];\n        const prev = bars[bars.length - 2];\n        let st = state.stocks.find(s => s.ticker === state.selectedTicker);\n        if (!st) {\n          st = { ticker: state.selectedTicker, name: `NSEKE:${state.selectedTicker}`, price: last.close, open: last.open, high: last.high, low: last.low, prevClose: prev ? prev.close : last.open, change: 0, changePct: 0, volume: last.volume };\n          state.stocks.unshift(st);\n        }\n        st.price = last.close;\n        st.open = last.open;\n        st.high = last.high;\n        st.low = last.low;\n        if (prev) st.prevClose = prev.close;\n        st.change = +(st.price - st.prevClose).toFixed(2);\n        st.changePct = st.prevClose ? +((st.change / st.prevClose) * 100).toFixed(2) : 0;\n        renderAll();\n        showToast(`Loaded ${bars.length} real OHLCV bars from CSV.`);\n      } else {\n        showToast(\'No valid OHLCV rows detected in CSV.\');\n      }\n    }\n\n    function bindEvents() {\n      document.getElementById(\'ws-btn-charts\').addEventListener(\'click\', () => switchWorkspace(\'charts\'));\n      document.getElementById(\'ws-btn-screener\').addEventListener(\'click\', () => switchWorkspace(\'screener\'));\n      document.getElementById(\'ws-btn-connectors\').addEventListener(\'click\', () => switchWorkspace(\'connectors\'));\n\n      const triggerFullScrape = async () => {\n        await tvScraper.scrapeAllNseSymbols();\n        await tvScraper.fetchDirectTradingViewWs(state.selectedTicker, state.timeframe, 500);\n      };\n\n      document.getElementById(\'sync-tv-btn\').addEventListener(\'click\', triggerFullScrape);\n      document.getElementById(\'overlay-retry-btn\').addEventListener(\'click\', triggerFullScrape);\n      document.getElementById(\'screener-rescrape-btn\').addEventListener(\'click\', () => tvScraper.scrapeAllNseSymbols());\n\n      document.getElementById(\'overlay-bridge-btn\').addEventListener(\'click\', () => switchWorkspace(\'connectors\'));\n      document.getElementById(\'overlay-csv-btn\').addEventListener(\'click\', () => document.getElementById(\'csv-modal\').classList.remove(\'hidden\'));\n      document.getElementById(\'connect-ws-bridge-btn\')?.addEventListener(\'click\', () => {\n        const wsUrl = document.getElementById(\'ws-bridge-url\')?.value?.trim() || \'ws://localhost:8765\';\n        tvScraper.connectLocalWsBridge(wsUrl);\n        switchWorkspace(\'charts\');\n      });\n\n      document.getElementById(\'fetch-rest-bridge-btn\')?.addEventListener(\'click\', () => {\n        const restUrl = document.getElementById(\'rest-bridge-url\')?.value?.trim() || \'\';\n        tvScraper.fetchLocalRestBridge(restUrl);\n        switchWorkspace(\'charts\');\n      });\n\n      document.getElementById(\'fetch-rest-bridge-btn\').addEventListener(\'click\', () => {\n        tvScraper.fetchLocalRestBridge(document.getElementById(\'rest-bridge-url\').value.trim());\n        switchWorkspace(\'charts\');\n      });\n\n      document.getElementById(\'watchlist-search\').addEventListener(\'input\', (e) => {\n        state.searchQuery = e.target.value;\n        renderWatchlist();\n      });\n\n      document.querySelectorAll(\'.tf-btn\').forEach(btn => {\n        btn.addEventListener(\'click\', () => {\n          document.querySelectorAll(\'.tf-btn\').forEach(b => b.classList.remove(\'active\'));\n          btn.classList.add(\'active\');\n          state.timeframe = btn.dataset.tf;\n          state.viewport.rightOffset = 0;\n          tvScraper.fetchDirectTradingViewWs(state.selectedTicker, state.timeframe, 500);\n          tvScraper.requestFromLocalBridge(state.selectedTicker, state.timeframe);\n          renderChart();\n        });\n      });\n\n      document.querySelectorAll(\'.style-btn\').forEach(btn => {\n        btn.addEventListener(\'click\', () => {\n          document.querySelectorAll(\'.style-btn\').forEach(b => b.classList.remove(\'active\'));\n          btn.classList.add(\'active\');\n          state.chartStyle = btn.dataset.style;\n          renderChart();\n        });\n      });\n\n      document.querySelectorAll(\'.tool-btn\').forEach(btn => {\n        btn.addEventListener(\'click\', () => {\n          document.querySelectorAll(\'.tool-btn\').forEach(b => b.classList.remove(\'active\'));\n          btn.classList.add(\'active\');\n          state.activeTool = btn.dataset.tool;\n        });\n      });\n\n      [\'sma20\', \'ema50\', \'bb\', \'vol\'].forEach(key => {\n        const el = document.getElementById(`ind-${key}`);\n        el.addEventListener(\'click\', () => {\n          state.indicators[key] = !state.indicators[key];\n          el.classList.toggle(\'active\', state.indicators[key]);\n          renderChart();\n        });\n      });\n\n      // Bottom Scale Navigation Buttons\n      document.getElementById(\'zoom-in-x-btn\').addEventListener(\'click\', () => {\n        state.viewport.visibleBars = Math.max(10, Math.round(state.viewport.visibleBars * 0.8));\n        renderChart();\n      });\n      document.getElementById(\'zoom-out-x-btn\').addEventListener(\'click\', () => {\n        state.viewport.visibleBars = Math.min(1000, Math.round(state.viewport.visibleBars * 1.25));\n        renderChart();\n      });\n      document.getElementById(\'pan-left-btn\').addEventListener(\'click\', () => {\n        state.viewport.rightOffset += Math.max(1, Math.round(state.viewport.visibleBars * 0.15));\n        renderChart();\n      });\n      document.getElementById(\'pan-right-btn\').addEventListener(\'click\', () => {\n        state.viewport.rightOffset = Math.max(0, state.viewport.rightOffset - Math.max(1, Math.round(state.viewport.visibleBars * 0.15)));\n        renderChart();\n      });\n      document.getElementById(\'jump-latest-btn\').addEventListener(\'click\', () => {\n        state.viewport.rightOffset = 0;\n        renderChart();\n      });\n      document.getElementById(\'reset-y-scale-btn\').addEventListener(\'click\', () => {\n        state.viewport.yZoom = 1.0;\n        state.viewport.yPanOffset = 0;\n        renderChart();\n      });\n      document.getElementById(\'reset-scales-btn\').addEventListener(\'click\', () => {\n        state.viewport.yZoom = 1.0;\n        state.viewport.yPanOffset = 0;\n        state.viewport.visibleBars = 90;\n        state.viewport.rightOffset = 0;\n        renderChart();\n      });\n      document.getElementById(\'clear-drawings-btn\').addEventListener(\'click\', () => {\n        state.drawings[state.selectedTicker] = [];\n        renderChart();\n      });\n\n      bindChartScaleInteractions();\n      window.addEventListener(\'resize\', renderChart);\n    }\n\n    window.addEventListener(\'DOMContentLoaded\', () => {\n      bindEvents();\n      renderAll();\n      tvScraper.scrapeAllNseSymbols();\n      tvScraper.fetchDirectTradingViewWs(state.selectedTicker, state.timeframe, 500);\n      updateEatClock();\n      setInterval(updateEatClock, 1000);\n    });\n  </script>\n</body>\n</html>'
